 {"source_id":"source.authority.token-revocation","title":"RFC 7009: OAuth 2.0 Token Revocation","publisher":"IETF / RFC Editor","url":"https://www.rfc-editor.org/rfc/rfc7009.html","bounded_implication":"A token can be invalidated through a revocation endpoint, with implications for related tokens and propagation.","authority_limit":"Revocation is not deletion, recall of prior disclosure, proof that caches have converged or reversal of completed effects."},
 {"source_id":"source.authority.token-introspection","title":"RFC 7662: OAuth 2.0 Token Introspection","publisher":"IETF / RFC Editor","url":"https://www.rfc-editor.org/rfc/rfc7662.html","bounded_implication":"A protected resource can query authorization-server state and metadata about a presented token, including whether it is currently active.","authority_limit":"An active token is not proof of subject identity, request appropriateness, business authority, policy freshness at every cache or completed enforcement."},
 {"source_id":"source.authority.vc","title":"Verifiable Credentials Data Model v2.0","publisher":"W3C","url":"https://www.w3.org/TR/vc-data-model-2.0/","bounded_implication":"Issuer, holder, verifier, credential subject, claims, validity, status and evidence are distinct; securing a credential protects it from undetected tampering.","authority_limit":"Verification does not prove claim truth, holder-subject identity, issuer authority for every purpose, current acceptance or authorization."},
 {"source_id":"source.authority.rats","title":"RFC 9334: RATS Architecture","publisher":"IETF / RFC Editor","url":"https://www.rfc-editor.org/rfc/rfc9334.html","bounded_implication":"Attester, Verifier and Relying Party roles separate evidence production, evidence appraisal, attestation results and application-specific relying decisions.","authority_limit":"Attestation integrity or a verifier result is not universal trust, application authorization, semantic fitness or absence of defects."},
